script:
(function () {
  'use strict';
  // Solo 401(k) vs SEP-IRA vs SIMPLE IRA: the most one owner-employee can put in for 2026 from the same
  // business income.
  // Sole proprietor / partner: net earnings = profit - deductible half of SE tax (Schedule SE); solo 401(k)
  // follows the Pub. 560 Deduction Worksheet for Self-Employed (steps 1-19) at a 25% plan rate (reduced rate
  // 0.25 / 1.25 = 20%); SEP = 20% of net earnings; SIMPLE uses Schedule SE net earnings before the SE
  // deduction (Pub. 560 ch. 3) with the 3% match. S/C corporation: everything is based on W-2 wages, the
  // employer rate is 25% of wages, and deferrals + employer money can't exceed wages (415(c)).
  // Checked in Node (scratchpad solo401k/tests/engine.test.js + ic.test.js): Pub. 560 (2025) worked example
  // with 2025 constants -> SE deduction $13,596, net earnings $186,404, step 6 $29,750 (Pub. rounds the
  // reduced rate to 0.078 and gets $14,540; the unrounded rate gives $14,603); 2026 $100,000 profit, age 40 ->
  // SE deduction $7,064.78 (matches self-employment-tax-calculator), net $92,935.23, employer $18,587.05, solo
  // 401(k) $43,087.05, SEP $18,587.05, SIMPLE $17,000 + 3% x $92,350 = $19,770.50 (standard limit);
  // $400,000 profit at 61 -> $72,000 + $11,250; $30,000 profit at 55 -> total capped at net earnings $27,880.57;
  // corporation $100,000 wages -> $24,500 + $25,000; $200,000 at 55 -> $80,000; SEP capped at $72,000.
  // ---- 2026 constants (tax year 2026) -------------------------------------------------------------
  // Plan limits: IRS Notice 2025-67. SIMPLE higher limits (employers with 25 or fewer employees, SECURE 2.0
  // sec. 117; automatic per Notice 2024-2 when the employer had no other plan in the prior 3 years): Notice
  // 2025-67. SE tax: Schedule SE / IRC 1401-1402; Social Security wage base $184,500 (SSA 2026, same constant
  // as self-employment-tax-calculator). Plan-rate conversion and worksheet: IRS Pub. 560 chapter 5.
  var Y = {
    year: 2026,
    deferral: 24500,        // 402(g) elective deferral limit, 401(k) (shared across all your 401(k)/403(b) plans)
    catchUp50: 8000,        // 414(v) catch-up, 401(k), age 50+
    catchUp60to63: 11250,   // 401(k) catch-up for ages 60-63
    annualAdditions: 72000, // 415(c) limit on deferrals + employer money (age catch-up excluded); also SEP cap
    compensation: 360000,   // 401(a)(17) / 408(k)(6)(D)(ii) pay limit for employer contributions
    employerRate: 0.25,     // maximum employer (profit-sharing / SEP) rate: 25% of pay, 20% of net SE earnings
    simple: {
      standard: { deferral: 17000, catchUp50: 4000, catchUp60to63: 5250 },   // 408(p)(2)(E)(i)(III), 414(v)(2)(B)(ii)
      small: { deferral: 18100, catchUp50: 3850, catchUp60to63: 5250 },      // 408(p)(2)(E)(i)(I)-(II), 414(v)(2)(B)(iii)
      matchRate: 0.03       // dollar-for-dollar match up to 3% of pay
    },
    se: { factor: 0.9235, ss: 0.124, med: 0.029, wageBase: 184500, floor: 400 }
  };
  // -------------------------------------------------------------------------------------------------

  function ageCatchUp(age, a50, a60) {
    if (age >= 60 && age <= 63) return a60;
    if (age >= 50) return a50;
    return 0;
  }
  function clamp0(x) { return x > 0 ? x : 0; }

  // Schedule SE: net earnings (line 4/6), SE tax and its deductible half. otherWages = W-2 Social Security
  // wages from a job, which use up part of the Social Security wage base.
  function seTax(profit, otherWages) {
    var line4 = profit > 0 ? profit * Y.se.factor : 0;
    var tax = line4 < Y.se.floor ? 0 : Y.se.ss * Math.min(line4, clamp0(Y.se.wageBase - otherWages)) + Y.se.med * line4;
    return { earnings: line4, tax: tax, half: tax / 2 };
  }

  // Solo 401(k) for a sole proprietor / partner: Pub. 560 Deduction Worksheet for Self-Employed, steps 1-19.
  // planRate = employer contribution rate stated in the plan (max 25%); reduced rate = planRate / (1 + planRate)
  // (Rate Worksheet; not rounded here). wantDeferral = total deferral wanted including catch-up (Infinity = max).
  function soloSoleProp(profit, age, otherWages, otherDeferrals, wantDeferral, planRate) {
    var se = seTax(profit, otherWages);
    var s = { s1: profit, s2: se.half, seTax: se.tax };
    s.s3 = clamp0(profit - se.half);
    s.s4 = planRate / (1 + planRate);
    s.s5 = s.s3 * s.s4;
    s.s6 = Y.compensation * planRate;
    s.s7 = Math.min(s.s5, s.s6);
    s.s8 = Y.annualAdditions;
    var basicRoom = clamp0(Y.deferral - otherDeferrals);
    s.s9 = Math.min(wantDeferral, basicRoom, s.s3);
    s.s10 = s.s8 - s.s9;
    s.s11 = s.s3 - s.s9;
    s.s12 = s.s11 / 2;
    s.s13 = Math.min(s.s7, s.s10, s.s12);
    s.s14 = s.s3 - s.s13;
    s.s15 = Math.min(s.s9, s.s14);
    s.s16 = s.s14 - s.s15;
    s.s17 = s.s9 >= basicRoom ? Math.min(clamp0(wantDeferral - s.s9), ageCatchUp(age, Y.catchUp50, Y.catchUp60to63)) : 0;
    s.s18 = Math.min(s.s16, s.s17);
    s.s19 = s.s13 + s.s15 + s.s18;
    return { deferral: s.s15, catchUp: s.s18, employer: s.s13, total: s.s19, comp: s.s3, steps: s };
  }

  // Solo 401(k) for an S or C corporation owner paid W-2 wages: deferrals come out of wages; the employer
  // adds planRate x wages (wages capped at the pay limit); deferrals + employer <= $72,000 and <= wages.
  function soloCorp(wages, age, otherDeferrals, wantDeferral, planRate) {
    var w = clamp0(wages);
    var deferral = Math.min(wantDeferral, clamp0(Y.deferral - otherDeferrals), w);
    var catchUp = deferral >= clamp0(Y.deferral - otherDeferrals)
      ? Math.min(clamp0(wantDeferral - deferral), ageCatchUp(age, Y.catchUp50, Y.catchUp60to63), w - deferral) : 0;
    var employer = Math.min(planRate * Math.min(w, Y.compensation), Y.annualAdditions - deferral, w - deferral);
    employer = clamp0(employer);
    return { deferral: deferral, catchUp: catchUp, employer: employer, total: deferral + catchUp + employer, comp: w };
  }

  // SEP-IRA: employer contributions only (no deferrals or catch-up).
  function sep(isCorp, income, otherWages) {
    var comp, employer;
    if (isCorp) { comp = clamp0(income); employer = Y.employerRate * Math.min(comp, Y.compensation); }
    else {
      comp = clamp0(income - seTax(income, otherWages).half);
      employer = Math.min(comp * Y.employerRate / (1 + Y.employerRate), Y.compensation * Y.employerRate);
    }
    employer = Math.min(employer, Y.annualAdditions);
    return { deferral: 0, catchUp: 0, employer: employer, total: employer, comp: comp };
  }

  // SIMPLE IRA: salary reduction up to the SIMPLE limit (also inside your 402(g) total), age catch-up, and the
  // 3% dollar-for-dollar match. Self-employed pay = Schedule SE net earnings before contributions (Pub. 560).
  function simpleIra(isCorp, income, age, otherWages, otherDeferrals, small) {
    var L = small ? Y.simple.small : Y.simple.standard;
    var comp = isCorp ? clamp0(income) : seTax(income, otherWages).earnings;
    var room = Math.min(L.deferral, clamp0(Y.deferral - otherDeferrals));
    var deferral = Math.min(room, comp);
    var catchUp = deferral >= room ? Math.min(ageCatchUp(age, L.catchUp50, L.catchUp60to63), comp - deferral) : 0;
    var employer = Math.min(deferral + catchUp, Y.simple.matchRate * comp);
    return { deferral: deferral, catchUp: catchUp, employer: employer, total: deferral + catchUp + employer, comp: comp };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function el(id) { return document.getElementById(id); }
  function set(id, t) { el(id).textContent = t; }
  function num(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function compare(isCorp, income, age, otherWages, otherDef, small) {
    var solo = isCorp ? soloCorp(income, age, otherDef, Infinity, Y.employerRate)
                      : soloSoleProp(income, age, otherWages, otherDef, Infinity, Y.employerRate);
    return { solo: solo, sep: sep(isCorp, income, otherWages),
             simple: simpleIra(isCorp, income, age, otherWages, otherDef, small) };
  }

  function update() {
    var isCorp = el('icType').value === 'corp', small = el('icSimple').value === 'small';
    set('icIncomeLabel', isCorp ? 'Your W-2 salary from the corporation' : 'Net business profit');
    set('icIncomeHint', isCorp ? 'Your gross salary before any 401(k) deferrals, usually the Medicare wages in box 5 of your W-2.'
      : 'Schedule C line 31 (or your share of partnership earnings), before any retirement contributions for yourself.');
    set('icLevelsCol', isCorp ? 'W-2 salary' : 'Net profit');
    el('icWagesWrap').hidden = isCorp;
    el('icWorksheet').hidden = isCorp;
    var income = num('icIncome', NaN), age = num('icAge', NaN), otherDef = num('icOtherDef', 0),
        otherWages = isCorp ? 0 : num('icWages', 0);
    var error = el('icError');
    var bad = [income, age, otherDef, otherWages].some(isNaN) || income < 0 || income > 100000000 ||
              age !== Math.round(age) || age < 16 || age > 99 || otherDef < 0 || otherWages < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a non-negative income, a whole-number age from 16 to 99 and non-negative amounts in More options.';
      return;
    }
    var r = compare(isCorp, income, age, otherWages, otherDef, small);
    set('icSoloTotal', fmt(r.solo.total)); set('icSepTotal', fmt(r.sep.total)); set('icSimpleTotal', fmt(r.simple.total));
    set('icSoloDef', fmt(r.solo.deferral)); set('icSoloCatch', fmt(r.solo.catchUp)); set('icSoloEr', fmt(r.solo.employer));
    set('icSoloSum', fmt(r.solo.total)); set('icSepEr', fmt(r.sep.employer)); set('icSepSum', fmt(r.sep.total));
    set('icSimpleDef', fmt(r.simple.deferral)); set('icSimpleCatch', fmt(r.simple.catchUp));
    set('icSimpleEr', fmt(r.simple.employer)); set('icSimpleSum', fmt(r.simple.total));
    var plans = [['Solo 401(k)', r.solo.total], ['SEP-IRA', r.sep.total], ['SIMPLE IRA', r.simple.total]];
    plans.sort(function (a, b) { return b[1] - a[1]; });
    if (plans[0][1] < 0.5) set('icVerdict', 'With no ' + (isCorp ? 'salary' : 'net self-employment earnings') +
      ' there is nothing you can contribute to any of these plans.');
    else if (plans[0][1] - plans[1][1] < 0.5) set('icVerdict', plans[0][0] + ' and ' + plans[1][0] + ' allow the same maximum of ' +
      fmt(plans[0][1]) + ' at this income.');
    else set('icVerdict', 'A ' + plans[0][0] + ' lets you put in the most: ' + fmt(plans[0][1]) + ', which is ' +
      fmt(plans[0][1] - plans[1][1]) + ' more than a ' + plans[1][0] + ' and ' + fmt(plans[0][1] - plans[2][1]) +
      ' more than a ' + plans[2][0] + '.');
    set('icErNote', isCorp
      ? 'Employer contributions are 25% of salary (salary counted up to ' + fmt(Y.compensation) + '). Pay from the corporation, ' +
        'not profit passed through to you, is what counts.'
      : 'Employer contributions for the self-employed are 20% of net earnings after the self-employment tax deduction; the ' +
        'SIMPLE IRA match is 3% of net earnings before that deduction. Self-employment tax: ' + fmt(seTax(income, otherWages).tax) + '.');
    if (!isCorp) {
      var s = r.solo.steps;
      set('icW1', fmt(s.s1)); set('icW2', '−' + fmt(s.s2)); set('icW3', fmt(s.s3)); set('icW5', fmt(s.s5));
      set('icW9', fmt(s.s15)); set('icW13', fmt(s.s13)); set('icW18', fmt(s.s18)); set('icW19', fmt(s.s19));
    }
    var levels = [25000, 50000, 75000, 100000, 150000, 200000, 300000, 400000];
    if (levels.indexOf(income) < 0 && income > 0) levels.push(income);
    levels.sort(function (a, b) { return a - b; });
    var body = el('icLevels');
    body.textContent = '';
    levels.forEach(function (inc) {
      var c = compare(isCorp, inc, age, otherWages, otherDef, small);
      var tr = document.createElement('tr');
      [fmt(inc) + (inc === income ? ' (yours)' : ''), fmt(c.solo.total), fmt(c.sep.total), fmt(c.simple.total)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('icForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
